-- ======== supabase/migrations/0002_profiles.sql ========
-- hushmallow · 0002 profiles
-- One row per account: an optional display name (at most 40 characters),
-- the home Mallow, when the account was created and last seen, and the
-- schema version. Created automatically for every new sign-up (trigger on
-- auth.users); accounts made before this script ran get theirs from
-- 0008_backfill_profiles.sql. Never words, feelings, thoughts or photos.
-- Requires 0001.

begin;

create table if not exists public.profiles (
  user_id        uuid primary key references auth.users (id) on delete cascade,
  display_name   text
                 check (display_name is null
                        or (char_length(display_name) between 1 and 40 and display_name !~ '[[:cntrl:]]')),
  home_mallow    text
                 check (home_mallow is null
                        or home_mallow in ('glitzi', 'blubi', 'zuzu', 'boppo', 'pipzi', 'loomi', 'noomi')),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  last_seen_at   timestamptz,
  schema_version smallint not null default 1 check (schema_version between 1 and 999)
);
comment on table public.profiles is 'hushmallow: one row per account. Display name (optional, <= 40 chars), home Mallow id, created / last seen, schema version. No free text beyond the name.';

alter table public.profiles enable row level security;
alter table public.profiles force row level security;

-- no anon access at all; the signed-in owner only, and only these columns
revoke all on table public.profiles from public;
revoke all on table public.profiles from anon, authenticated;
grant select, delete on table public.profiles to authenticated;
grant insert (user_id, display_name, home_mallow) on table public.profiles to authenticated;
grant update (display_name, home_mallow, last_seen_at) on table public.profiles to authenticated;

drop policy if exists profiles_select_own on public.profiles;
drop policy if exists profiles_insert_own on public.profiles;
drop policy if exists profiles_update_own on public.profiles;
drop policy if exists profiles_delete_own on public.profiles;
create policy profiles_select_own on public.profiles
  for select to authenticated
  using ((select auth.uid()) = user_id);
create policy profiles_insert_own on public.profiles
  for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy profiles_update_own on public.profiles
  for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);
create policy profiles_delete_own on public.profiles
  for delete to authenticated
  using ((select auth.uid()) = user_id);

-- the server owns created_at, updated_at, schema_version and the last-seen time
create or replace function hm_private.profiles_stamp()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.schema_version := 1;
    new.last_seen_at := case when new.last_seen_at is null then null else now() end;
  else
    new.user_id := old.user_id;
    new.created_at := old.created_at;
    new.schema_version := old.schema_version;
    if new.last_seen_at is distinct from old.last_seen_at then
      new.last_seen_at := now();
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function hm_private.profiles_stamp() from public;
revoke all on function hm_private.profiles_stamp() from anon, authenticated;

create or replace trigger profiles_stamp
  before insert or update on public.profiles
  for each row execute function hm_private.profiles_stamp();

-- a profile for every new sign-up (the name, if one was given, cleaned and capped)
create or replace function hm_private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text;
begin
  v_name := nullif(btrim(regexp_replace(coalesce(new.raw_user_meta_data ->> 'display_name', ''), '[[:cntrl:]]', '', 'g')), '');
  if v_name is not null then
    v_name := left(v_name, 40);
  end if;
  insert into public.profiles (user_id, display_name)
  values (new.id, v_name)
  on conflict (user_id) do nothing;
  return new;
end;
$$;
revoke all on function hm_private.handle_new_user() from public;
revoke all on function hm_private.handle_new_user() from anon, authenticated;

create or replace trigger on_auth_user_created
  after insert on auth.users
  for each row execute function hm_private.handle_new_user();

insert into hm_private.schema_migrations (version, name) values (2, '0002_profiles')
on conflict (version) do nothing;

commit;

-- ======== supabase/migrations/0003_sync_consents.sql ========
-- hushmallow · 0003 sync consents
-- The person's two opt-in choices, both OFF until they turn them on:
--   settings_sync  "Sync my settings"                              → public.preferences
--   library_sync   "Keep my favourites and progress with my account" → favourite_worlds,
--                  garden_skills, hushflow_progress
-- The server stamps when each was given (…_sync_at) and withdrawn
-- (…_withdrawn_at). Withdrawing deletes the synced rows (0006). The synced
-- tables refuse writes unless the matching consent is on (0004, 0005).
-- A missing row means both are off. Requires 0001.

begin;

create table if not exists public.sync_consents (
  user_id               uuid primary key references auth.users (id) on delete cascade,
  settings_sync         boolean not null default false,
  settings_sync_at      timestamptz,
  settings_withdrawn_at timestamptz,
  library_sync          boolean not null default false,
  library_sync_at       timestamptz,
  library_withdrawn_at  timestamptz,
  consent_version       smallint not null default 1 check (consent_version between 1 and 999),
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);
comment on table public.sync_consents is 'hushmallow: opt-in consent to keep settings / favourites and progress with the account, with server timestamps for giving and withdrawing.';

alter table public.sync_consents enable row level security;
alter table public.sync_consents force row level security;

revoke all on table public.sync_consents from public;
revoke all on table public.sync_consents from anon, authenticated;
grant select, delete on table public.sync_consents to authenticated;
grant insert (user_id, settings_sync, library_sync) on table public.sync_consents to authenticated;
grant update (settings_sync, library_sync) on table public.sync_consents to authenticated;

drop policy if exists sync_consents_select_own on public.sync_consents;
drop policy if exists sync_consents_insert_own on public.sync_consents;
drop policy if exists sync_consents_update_own on public.sync_consents;
drop policy if exists sync_consents_delete_own on public.sync_consents;
create policy sync_consents_select_own on public.sync_consents
  for select to authenticated
  using ((select auth.uid()) = user_id);
create policy sync_consents_insert_own on public.sync_consents
  for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy sync_consents_update_own on public.sync_consents
  for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);
create policy sync_consents_delete_own on public.sync_consents
  for delete to authenticated
  using ((select auth.uid()) = user_id);

-- the timestamps are the server's: given when a switch turns on, withdrawn when it turns off
create or replace function hm_private.sync_consents_stamp()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.settings_sync_at := case when new.settings_sync then now() else null end;
    new.settings_withdrawn_at := null;
    new.library_sync_at := case when new.library_sync then now() else null end;
    new.library_withdrawn_at := null;
  else
    new.user_id := old.user_id;
    new.created_at := old.created_at;
    new.settings_sync_at := case when new.settings_sync and not old.settings_sync then now() else old.settings_sync_at end;
    new.settings_withdrawn_at := case when old.settings_sync and not new.settings_sync then now() else old.settings_withdrawn_at end;
    new.library_sync_at := case when new.library_sync and not old.library_sync then now() else old.library_sync_at end;
    new.library_withdrawn_at := case when old.library_sync and not new.library_sync then now() else old.library_withdrawn_at end;
  end if;
  new.consent_version := 1;
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function hm_private.sync_consents_stamp() from public;
revoke all on function hm_private.sync_consents_stamp() from anon, authenticated;

create or replace trigger sync_consents_stamp
  before insert or update on public.sync_consents
  for each row execute function hm_private.sync_consents_stamp();

insert into hm_private.schema_migrations (version, name) values (3, '0003_sync_consents')
on conflict (version) do nothing;

commit;

-- ======== supabase/migrations/0004_preferences.sql ========
-- hushmallow · 0004 preferences ("Sync my settings", opt-in)
-- The app's settings as switches and fixed values only (no free text):
-- sound, volume, haptics, motion, low stimulation, the history switch, the
-- saved-angles switch, intro seen, auto-flow, subtitle speed, text size and
-- the home Mallow. Written only while sync_consents.settings_sync is on
-- (the policy checks it); withdrawing deletes the row (0006).
-- Requires 0001 and 0003.

begin;

create table if not exists public.preferences (
  user_id        uuid primary key references auth.users (id) on delete cascade,
  sound          boolean not null default true,
  volume         numeric(3, 2) not null default 0.60 check (volume between 0 and 1),
  haptics        boolean not null default true,
  motion         text not null default 'system' check (motion in ('system', 'reduced', 'full')),
  low_stim       boolean not null default false,
  save_history   boolean not null default true,
  save_words     boolean not null default false,
  seen_intro     boolean not null default false,
  auto_flow      boolean not null default false,
  subtitle_speed numeric(3, 2) not null default 1 check (subtitle_speed in (0.75, 1, 1.25, 1.5)),
  text_scale     numeric(3, 2) not null default 1 check (text_scale in (1, 1.12, 1.25)),
  mallow         text check (mallow is null or mallow in ('glitzi', 'blubi', 'zuzu', 'boppo', 'pipzi', 'loomi', 'noomi')),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
comment on table public.preferences is 'hushmallow: synced settings (opt-in, sync_consents.settings_sync). Switches and fixed values only.';

alter table public.preferences enable row level security;
alter table public.preferences force row level security;

revoke all on table public.preferences from public;
revoke all on table public.preferences from anon, authenticated;
grant select, insert, update, delete on table public.preferences to authenticated;

drop policy if exists preferences_select_own on public.preferences;
drop policy if exists preferences_insert_own on public.preferences;
drop policy if exists preferences_update_own on public.preferences;
drop policy if exists preferences_delete_own on public.preferences;
create policy preferences_select_own on public.preferences
  for select to authenticated
  using ((select auth.uid()) = user_id);
create policy preferences_insert_own on public.preferences
  for insert to authenticated
  with check (
    (select auth.uid()) = user_id
    and exists (select 1 from public.sync_consents c where c.user_id = (select auth.uid()) and c.settings_sync)
  );
create policy preferences_update_own on public.preferences
  for update to authenticated
  using ((select auth.uid()) = user_id)
  with check (
    (select auth.uid()) = user_id
    and exists (select 1 from public.sync_consents c where c.user_id = (select auth.uid()) and c.settings_sync)
  );
create policy preferences_delete_own on public.preferences
  for delete to authenticated
  using ((select auth.uid()) = user_id);

create or replace function hm_private.keep_created_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
  else
    new.created_at := old.created_at;
  end if;
  return new;
end;
$$;
revoke all on function hm_private.keep_created_at() from public;
revoke all on function hm_private.keep_created_at() from anon, authenticated;

create or replace trigger preferences_created
  before insert or update on public.preferences
  for each row execute function hm_private.keep_created_at();
create or replace trigger preferences_updated_at
  before insert or update on public.preferences
  for each row execute function hm_private.set_updated_at();

