-- ======== supabase/migrations/0006_consent_withdrawal.sql ========
-- hushmallow · 0006 withdrawing consent deletes what was synced
-- Turning "Sync my settings" off deletes the account's preferences row;
-- turning "Keep my favourites and progress with my account" off deletes its
-- favourite_worlds, garden_skills and hushflow_progress rows. Deleting the
-- consent row withdraws both. Runs with the rights of whoever changed the
-- consent (the account itself through the app), so Row Level Security still
-- limits it to that account's own rows. Requires 0001 to 0005.

begin;

create or replace function hm_private.sync_consents_withdrawn()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  was_settings boolean := old.settings_sync;
  was_library  boolean := old.library_sync;
  now_settings boolean := case when tg_op = 'DELETE' then false else new.settings_sync end;
  now_library  boolean := case when tg_op = 'DELETE' then false else new.library_sync end;
begin
  if was_settings and not now_settings then
    delete from public.preferences where user_id = old.user_id;
  end if;
  if was_library and not now_library then
    delete from public.favourite_worlds where user_id = old.user_id;
    delete from public.garden_skills where user_id = old.user_id;
    delete from public.hushflow_progress where user_id = old.user_id;
  end if;
  return null;
end;
$$;
revoke all on function hm_private.sync_consents_withdrawn() from public;
revoke all on function hm_private.sync_consents_withdrawn() from anon, authenticated;

create or replace trigger sync_consents_withdrawn
  after update or delete on public.sync_consents
  for each row execute function hm_private.sync_consents_withdrawn();

insert into hm_private.schema_migrations (version, name) values (6, '0006_consent_withdrawal')
on conflict (version) do nothing;

commit;

-- ======== supabase/migrations/0007_delete_my_account.sql ========
-- hushmallow · 0007 delete_my_account()
-- "Delete account" in the app calls this (POST /rest/v1/rpc/delete_my_account
-- with the person's own session). It takes no arguments: it can only ever
-- delete the caller, auth.uid(). It deletes every hushmallow row the account
-- owns and then its auth.users row, whose foreign keys cascade to anything
-- left (profiles, consents, synced rows) and, inside Supabase Auth, to its
-- identities, sessions and refresh tokens. Only the authenticated role may
-- execute it; anon and public may not.
-- SECURITY DEFINER because deleting from auth.users needs the owner's rights;
-- search_path is empty and every name is schema-qualified.
-- Requires 0001 to 0006.

begin;

create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null or coalesce(auth.jwt() ->> 'role', '') <> 'authenticated' then
    raise exception 'sign in to delete your account' using errcode = '42501';
  end if;
  delete from public.hushflow_progress where user_id = v_uid;
  delete from public.garden_skills where user_id = v_uid;
  delete from public.favourite_worlds where user_id = v_uid;
  delete from public.preferences where user_id = v_uid;
  delete from public.sync_consents where user_id = v_uid;
  delete from public.profiles where user_id = v_uid;
  delete from auth.users where id = v_uid;
  if not found then
    raise exception 'no such account' using errcode = 'P0002';
  end if;
  return jsonb_build_object('deleted', true);
end;
$$;
comment on function public.delete_my_account() is 'hushmallow: deletes the calling account (auth.uid()) and all of its rows. No arguments; authenticated only.';
revoke all on function public.delete_my_account() from public;
revoke all on function public.delete_my_account() from anon;
grant execute on function public.delete_my_account() to authenticated;

insert into hm_private.schema_migrations (version, name) values (7, '0007_delete_my_account')
on conflict (version) do nothing;

commit;

-- ======== supabase/migrations/0008_backfill_profiles.sql ========
-- hushmallow · 0008 backfill profiles
-- Accounts created before 0002 put its trigger on auth.users have no
-- profile row. This adds one for each (display name from the sign-up
-- metadata, cleaned and capped like the trigger does). It changes nothing
-- for accounts that already have one and is safe to run again at any time.
-- Requires 0002.

begin;

insert into public.profiles (user_id, display_name)
select u.id,
       left(nullif(btrim(regexp_replace(coalesce(u.raw_user_meta_data ->> 'display_name', ''), '[[:cntrl:]]', '', 'g')), ''), 40)
from auth.users u
where not exists (select 1 from public.profiles p where p.user_id = u.id)
on conflict (user_id) do nothing;

insert into hm_private.schema_migrations (version, name) values (8, '0008_backfill_profiles')
on conflict (version) do nothing;

commit;

-- ======== supabase/migrations/0009_row_cap_upserts.sql ========
-- hushmallow · 0009 row cap counts new rows only
-- 0005's cap (at most 64 favourite worlds / 64 Memory Garden tools per
-- account) is a BEFORE INSERT trigger, and an upsert (INSERT … ON CONFLICT
-- DO UPDATE, which the app's sync sends) fires it for rows that already
-- exist: with 64 rows kept, every later sync of the same 64 was refused
-- (23514). The cap now lets a row whose key is already there through (it
-- becomes an update) and counts only genuinely new keys. Same function name,
-- same triggers; safe to run again at any time. Requires 0005.

begin;

create or replace function hm_private.enforce_row_cap()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  n integer;
begin
  if tg_table_name = 'favourite_worlds' then
    -- already kept: the upsert updates it, nothing new is added
    if exists (select 1 from public.favourite_worlds f where f.user_id = new.user_id and f.world_id = new.world_id) then
      return new;
    end if;
    select count(*) into n from public.favourite_worlds where user_id = new.user_id;
  elsif tg_table_name = 'garden_skills' then
    if exists (select 1 from public.garden_skills g where g.user_id = new.user_id and g.skill_id = new.skill_id) then
      return new;
    end if;
    select count(*) into n from public.garden_skills where user_id = new.user_id;
  else
    return new;
  end if;
  if n >= 64 then
    raise exception 'hushmallow keeps at most 64 of these per account' using errcode = '23514';
  end if;
  return new;
end;
$$;
revoke all on function hm_private.enforce_row_cap() from public;
revoke all on function hm_private.enforce_row_cap() from anon, authenticated;

insert into hm_private.schema_migrations (version, name) values (9, '0009_row_cap_upserts')
on conflict (version) do nothing;

commit;
